const fs = require('fs');
const path = require('path');
const assert = require('assert');

// Test the actual rendered HTML generated by renderProfileFacilityList logic
const appJsContent = fs.readFileSync(path.join(__dirname, '../js/app.js'), 'utf8');

// Ensure no [${fac.code}] or [${bCode}] remains anywhere in app.js
assert(!appJsContent.includes('[${fac.code}]'), 'Error: [${fac.code}] still found in js/app.js');
assert(!appJsContent.includes('[${bCode}]'), 'Error: [${bCode}] still found in js/app.js');
assert(!appJsContent.includes('[${p.branch_code'), 'Error: [${p.branch_code found in js/app.js');

// Mock data
const mockPlants = [
  { id: 'PLANT-01', name: 'Mauli Service Center 1', code: 'BRANCH-01', branch_code: '01' },
  { id: 'PLANT-02', name: 'Mauli Service Center 2', code: 'BRANCH-02', branch_code: '02' }
];

const allOptions = [
  {
    id: 'ALL',
    name: 'All Branches (Consolidated)',
    code: 'CORP-OVERVIEW',
    location: 'Consolidated Enterprise View'
  },
  ...mockPlants.map(p => ({
    id: p.id,
    name: p.name,
    code: p.branch_code || (p.code ? p.code.replace('BRANCH-', '') : (p.city || 'PUN').substring(0, 3)).toUpperCase(),
    location: `${p.city || ''}, ${p.state || ''}`.replace(/^, |, $/g, '') || 'Branch Workshop'
  }))
];

const currentPlantId = 'PLANT-01';

const renderedProfileSelect = `
  <div class="profile-facility-dropdown-wrapper">
    <select 
      id="profile-facility-select" 
      class="form-control profile-facility-select" 
      onchange="window.App.switchFacility(this.value)"
      title="Select Working Branch"
    >
      ${allOptions.map(fac => `<option value="${fac.id}" ${fac.id === currentPlantId ? 'selected' : ''}>${fac.name}</option>`).join('')}
    </select>
  </div>
`;

console.log('Rendered profile select HTML:\n', renderedProfileSelect);

// Verify no square brackets in option texts
const optionMatches = [...renderedProfileSelect.matchAll(/<option[^>]*>(.*?)<\/option>/g)];
assert.strictEqual(optionMatches.length, 3, 'Should have 3 options');

optionMatches.forEach((m, idx) => {
  const text = m[1];
  console.log(`Option ${idx + 1}: "${text}"`);
  assert(!text.includes('['), `Option text "${text}" should NOT contain '['`);
  assert(!text.includes(']'), `Option text "${text}" should NOT contain ']'`);
  assert(!text.includes('01]'), `Option text "${text}" should NOT contain branch code`);
  assert(!text.includes('CORP-OVERVIEW'), `Option text "${text}" should NOT contain CORP-OVERVIEW`);
});

console.log('\n✅ All tests passed! All codes successfully removed from branch select options.');
